(async()=>{if(!document.getElementById('hazard-rows'))return;const u=EamWorkUi,$=u.$,api=EamProblemApi;let rows=[],config={},page=1,current=null,command='',busy=false,detailToken=0,commandTarget=null;
function draw(){const filtered=rows.filter(r=>(!$('hazard-search').value||[r.id,r.description].join(' ').includes($('hazard-search').value))&&(!$('hazard-authority').value||r.authority===$('hazard-authority').value));const pages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,pages);$('hazard-rows').replaceChildren();for(const r of filtered.slice((page-1)*8,page*8)){const title=u.link('',()=>detail(r.id));title.append(u.node('strong',r.id+' · '+r.description),u.node('small',r.part));const authority=u.node('div',r.assessmentRequired?'待风险核实':r.major?'重大（权威示例）':'一般');authority.append(u.node('small',r.authority==='EHS'?'EHS权威 · '+r.externalId:'EAM治理'));const owner=u.node('div',u.name(r.ownerId));owner.append(u.node('small','截止 '+r.dueAt));u.row($('hazard-rows'),[title,authority,u.badge(r.status),owner,r.restriction?.status==='released'?'已放行':'限制有效',u.button('查看与处理',()=>detail(r.id))],['隐患 / 范围','分类 / 权威','治理状态','责任人 / 期限','使用限制','操作']);}$('hazard-total').textContent=rows.length;$('hazard-open').textContent=rows.filter(r=>r.status!=='closed').length;$('hazard-review').textContent=rows.filter(r=>r.status==='pending_review').length;$('hazard-restrictions').textContent=rows.filter(r=>r.restriction?.status==='active').length;$('hazard-empty').hidden=!!filtered.length;$('hazard-count').textContent=EamUiComponents.paginationText(filtered.length,page,pages);$('hazard-prev').disabled=page===1;$('hazard-next').disabled=page===pages;EamUiComponents.pagination($('hazard-count').parentElement,{page,pages:pages,total:filtered.length,pageSize:8,countId:'hazard-count',previousId:'hazard-prev',nextId:'hazard-next',onChange:nextPage=>{page=nextPage;draw();}});EamUiComponents.syncTableState($('hazard-rows').closest('table'));}
async function load(){$('hazard-load').textContent='正在读取…';try{rows=EamArchiveContext.filter((await api.request('GET','/hazards')).rows,location.search);draw();$('hazard-load').textContent='已读取 · '+rows.length+'条范围记录';}catch(e){$('hazard-load').textContent=e.message;$('hazard-rows').replaceChildren();}}
async function detail(id){const token=++detailToken;try{const result=await api.request('GET','/hazards/'+id);if(token!==detailToken)return;EamArchiveContext.assertRecord(result,location.search);current=result;const r=current;$('hazard-id').textContent=r.id+' · V'+r.version;$('hazard-detail-title').textContent=r.description;$('hazard-badges').replaceChildren(u.badge(r.status),u.badge(r.priority));u.facts($('hazard-facts'),[['设备',r.equipmentId],['主责',u.name(r.ownerId)],['截止日期',r.dueAt],['风险分类',r.assessmentRequired?'待安全核实':r.major?'重大（权威示例）':'一般'],['治理权威',r.authority==='EHS'?'EHS / '+r.externalId+' / V'+r.externalVersion:'EAM治理'],['使用限制',r.restriction?.status==='released'?'已独立放行':'限制仍有效']]);$('hazard-controls').textContent=r.control?r.control.description+' / '+r.control.evidence+' / 有效至 '+EamProduct.time(r.control.validUntil):'尚未登记有效控制措施';$('hazard-evidence').textContent=[r.evidence,r.assessment&&'风险核实依据：'+r.assessment.basis,r.review&&'安全复查：'+r.review.reason+' / '+r.review.evidence,r.authorityReceipt&&'权威回执：'+r.authorityReceipt.verifiedBy].filter(Boolean).join('；');$('hazard-actions').replaceChildren();for(const action of r.actions)$('hazard-actions').append(u.button(config.actionLabels[action],()=>{ $('hazard-detail').close();openCommand(action);},['review','release'].includes(action)?'primary':''));$('hazard-work').hidden=r.status==='closed'||!['engineer','supervisor'].includes(Eam.s.role);$('hazard-work').onclick=()=>Eam.go('order-list',{create:'1',problemKind:'hazards',problemId:r.id});$('hazard-equipment').onclick=()=>Eam.go('device',{equipment:r.equipmentId,tab:'risk'});$('hazard-authority-note').textContent=r.authority==='EHS'?'外部权威隐患在EAM只做技术整改协同，禁止本地审批关闭。回执为预定义JSON评审样本，未连接真实EHS。':'整改复查通过不解除使用限制；安全放行须单独留证。';u.audit($('hazard-audit'),r.audit);$('hazard-detail').showModal();}catch(e){Eam.message(e.message);}}
function openCommand(action){commandTarget={id:current.id,version:current.version};command=action;$('hazard-command-form').reset();$('hazard-command-title').textContent=config.actionLabels[action];$('hazard-error').textContent='';for(const [id,show]of [['hazard-classification-field',action==='assess'],['hazard-control-field',action==='control'],['hazard-control-until-field',action==='control'],['hazard-decision-field',action==='review'],['hazard-receipt-field',action==='sync'],['hazard-evidence-field',action!=='sync']])$(id).hidden=!show;$('hazard-command').showModal();}
$('hazard-command-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('hazard-command-submit').disabled=true;try{await api.request('POST','/hazards/'+commandTarget.id+'/'+command,{expectedVersion:commandTarget.version,reason:$('hazard-reason').value,evidence:$('hazard-command-evidence').value,control:$('hazard-control').value,validUntil:$('hazard-control-until').value,classification:$('hazard-classification').value,decision:$('hazard-decision').value,receiptId:$('hazard-receipt').value});$('hazard-command').close();await load();await detail(commandTarget.id);Eam.message('隐患操作已保存；其他问题及工单不自动关闭');}catch(error){$('hazard-error').textContent=error.message+'；输入已保留。';}finally{busy=false;$('hazard-command-submit').disabled=false;}};
$('hazard-create').onclick=()=>Eam.go('abnormal-events',{create:'1',problemKind:'hazards'});$('hazard-refresh').onclick=load;$('hazard-detail-close').onclick=()=>$('hazard-detail').close();$('hazard-command-cancel').onclick=()=>$('hazard-command').close();for(const id of ['hazard-search','hazard-authority'])$(id).addEventListener(id==='hazard-search'?'input':'change',()=>{page=1;draw();});$('hazard-clear').onclick=()=>{$('hazard-search').value='';$('hazard-authority').value='';page=1;draw();};$('hazard-prev').onclick=()=>{page--;draw();};$('hazard-next').onclick=()=>{page++;draw();};try{config=await u.init();for(const receipt of config.externalReceipts)$('hazard-receipt').add(new Option(receipt.id+' · V'+receipt.externalVersion,receipt.id));await load();const id=new URLSearchParams(location.search).get('id');if(id)await detail(id);}catch(e){$('hazard-load').textContent=e.message;}
})();
